// rr_arbiter.v
// Round-robin arbiter: N requesters share one resource; at most one is
// granted per cycle.
//
// Implements microarchitecture.md (rr_arbiter):
//   1. State: one priority pointer `ptr`, $clog2(N) bits, reset to 0.
//   2. Grant logic: a wrapping priority search from `ptr`, wrapping from
//      N-1 to 0 by comparing against LAST, so N need not be a power of two.
//      Every output of the block gets a default before the loop (no latch).
//   3. Pointer update: on a rising edge with a grant, ptr <= winner + 1
//      (wrapping at N); with no request, ptr holds.
//   4. Reset: rst_n synchronous, active low; grant is not gated by reset.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW     = $clog2(N);
    localparam integer  LAST_I = N - 1;
    localparam [PW-1:0] LAST   = LAST_I[PW-1:0];

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg [PW-1:0] winner;
    reg [PW-1:0] idx;
    reg          found;
    integer      i;

    // Wrapping priority search from the pointer, and the next pointer.
    always @* begin
        grant  = {N{1'b0}};
        winner = {PW{1'b0}};
        found  = 1'b0;
        idx    = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[idx]) begin
                found      = 1'b1;
                winner     = idx;
                grant[idx] = 1'b1;
            end
            idx = (idx == LAST) ? {PW{1'b0}} : idx + 1'b1;
        end
        if (found) begin
            ptr_next = (winner == LAST) ? {PW{1'b0}} : winner + 1'b1;
        end else begin
            ptr_next = ptr;
        end
    end

    // Pointer register: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Pointer in range; grant one-hot or zero, only to a requester,
    // work conserving; the winner is the granted requester.
    always @(*) begin
        assert(ptr <= LAST);
        assert((grant & (grant - 1'b1)) == {N{1'b0}});
        assert((grant & ~req) == {N{1'b0}});
        if (req != {N{1'b0}}) assert(grant != {N{1'b0}});
        if (found) assert(grant[winner] && req[winner]);
    end

    // Round-robin order: no requester sits between the pointer and the winner.
    integer f_j;
    always @(*) begin
        if (found) begin
            for (f_j = 0; f_j < N; f_j = f_j + 1) begin
                if (((f_j - ptr + N) % N) < ((winner - ptr + N) % N))
                    assert(!req[f_j]);
            end
        end
    end

    // Pointer is 0 after reset, one past the winner after a grant,
    // and holds when nothing was granted.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert(ptr == {PW{1'b0}});
            else if ($past(found))
                assert(ptr == (($past(winner) == LAST) ? {PW{1'b0}}
                                                       : $past(winner) + 1'b1));
            else
                assert(ptr == $past(ptr));
        end
    end

    // Fairness: cycles waited with the request held never exceed N-1;
    // induction invariant: wait plus the pointer's distance stays within N-1.
    genvar f_g;
    generate
        for (f_g = 0; f_g < N; f_g = f_g + 1) begin : g_fair
            reg [PW:0] f_wait;
            initial f_wait = {(PW+1){1'b0}};
            always @(posedge clk) begin
                if (!rst_n || !req[f_g] || grant[f_g])
                    f_wait <= {(PW+1){1'b0}};
                else
                    f_wait <= f_wait + 1'b1;
            end
            always @(*) begin
                assert(f_wait <= LAST_I);
                if (f_wait != {(PW+1){1'b0}})
                    assert((f_wait + ((f_g - ptr + N) % N)) <= LAST_I);
            end
            always @(*) cover(rst_n && grant[f_g]);
        end
    endgenerate

    // Covers: everyone requesting, and the pointer wrapping from N-1 to 0.
    always @(*) cover(rst_n && (req == {N{1'b1}}));
    always @(posedge clk) begin
        if (f_past_valid)
            cover($past(rst_n) && ($past(ptr) == LAST) && (ptr == {PW{1'b0}}));
    end
`endif

endmodule
=== END FILE ===
