// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter (interface_spec.md section 6).
// Two harnesses run side by side, N = 4 (default) and N = 5 (not a power
// of two). Each checks grant on every rising edge against a reference
// pointer model, checks the N-1 wait bound per requester, runs directed
// rotation checks, and fails the run if a required case was not reached.
// Inputs are driven on the falling edge; checks are made on the rising edge.

module rr_arbiter_tb_harness #(
    parameter integer N    = 4,
    parameter [31:0]  SEED = 32'h1F2E3D4C
) (
    input  wire        clk,
    output reg         done,
    output wire [31:0] passed,
    output wire [31:0] failed
);

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Check counters: chk_* written only by the checker block,
    // dir_* written only by the stimulus block.
    integer chk_pass = 0;
    integer chk_fail = 0;
    integer dir_pass = 0;
    integer dir_fail = 0;
    assign passed = chk_pass + dir_pass;
    assign failed = chk_fail + dir_fail;

    // Reference model: first requester at or after p, wrapping at N.
    function integer exp_winner;
        input [N-1:0] r;
        input integer p;
        integer k;
        integer idx;
        begin
            exp_winner = -1;
            for (k = N - 1; k >= 0; k = k - 1) begin
                idx = (p + k) % N;
                if (r[idx]) exp_winner = idx;
            end
        end
    endfunction

    // ------------------------------------------------------------------
    // Checker: every rising edge.
    // ------------------------------------------------------------------
    reg          model_valid = 1'b0;
    integer      ref_ptr     = 0;
    integer      w_exp;
    reg  [N-1:0] g_exp;
    reg  [N-1:0] onek;
    reg  [N-1:0] prev_req    = {N{1'b0}};
    reg          prev_rst_n  = 1'b0;
    integer      waitc [0:N-1];
    integer      max_wait    = 0;
    integer      cov_none    = 0;
    integer      cov_all     = 0;
    integer      cov_held    = 0;
    integer      cov_rst     = 0;
    reg  [N-1:0] cov_alone   = {N{1'b0}};
    reg          fair_ok;
    integer      k;
    integer      cyc         = 0;

    always @(posedge clk) begin
        cyc   = cyc + 1;
        w_exp = exp_winner(req, ref_ptr);
        if (model_valid) begin
            // Exact grant against the reference pointer model.
            g_exp = {N{1'b0}};
            if (w_exp >= 0) g_exp[w_exp] = 1'b1;
            if (grant === g_exp) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("rr_arbiter N=%0d cycle %0d: grant %b, expected %b (req %b, model pointer %0d, rst_n %b)",
                       N, cyc, grant, g_exp, req, ref_ptr, rst_n);
            end

            // Grant properties: one-hot or zero, only to a requester, work conserving.
            if (((grant & (grant - 1'b1)) == {N{1'b0}}) &&
                ((grant & ~req) == {N{1'b0}}) &&
                ((req == {N{1'b0}}) || (grant != {N{1'b0}}))) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("rr_arbiter N=%0d cycle %0d: grant %b breaks one-hot/request/work-conserving rules (req %b)",
                       N, cyc, grant, req);
            end

            // Fairness: no held request waits more than N-1 cycles.
            fair_ok = 1'b1;
            for (k = 0; k < N; k = k + 1) begin
                if (!rst_n || !req[k] || grant[k]) begin
                    waitc[k] = 0;
                end else begin
                    waitc[k] = waitc[k] + 1;
                    if (waitc[k] > max_wait) max_wait = waitc[k];
                    if (waitc[k] > N - 1) begin
                        fair_ok = 1'b0;
                        $error("rr_arbiter N=%0d cycle %0d: requester %0d has waited %0d cycles (bound %0d)",
                               N, cyc, k, waitc[k], N - 1);
                    end
                end
            end
            if (fair_ok) chk_pass = chk_pass + 1;
            else         chk_fail = chk_fail + 1;

            // Coverage.
            if (rst_n && (req == {N{1'b0}})) cov_none = cov_none + 1;
            if (rst_n && (req == {N{1'b1}})) cov_all  = cov_all + 1;
            if (!rst_n && prev_rst_n && (req != {N{1'b0}})) cov_rst = cov_rst + 1;
            for (k = 0; k < N; k = k + 1) begin
                onek    = {N{1'b0}};
                onek[k] = 1'b1;
                if (rst_n && (req == onek) && (grant == onek)) cov_alone[k] = 1'b1;
                if (rst_n && prev_rst_n && req[k] && prev_req[k] &&
                    (((req ^ prev_req) & ~onek) != {N{1'b0}}))
                    cov_held = cov_held + 1;
            end
        end

        // Model update.
        if (!rst_n) begin
            ref_ptr     = 0;
            model_valid = 1'b1;
        end else if (model_valid && (w_exp >= 0)) begin
            ref_ptr = (w_exp + 1) % N;
        end
        prev_req   = req;
        prev_rst_n = rst_n;
    end

    // ------------------------------------------------------------------
    // Stimulus.
    // ------------------------------------------------------------------
    reg  [31:0]  rnd = SEED;
    reg  [N-1:0] sel;
    integer      s;
    integer      t;

    task next_rnd;
        begin
            rnd = rnd ^ (rnd << 13);
            rnd = rnd ^ (rnd >> 17);
            rnd = rnd ^ (rnd << 5);
        end
    endtask

    // Called on a falling edge right after reset release, with everyone
    // requesting: grants must rotate 0, 1, ..., N-1, 0, ...
    task check_rotation;
        input integer rounds;
        integer r;
        begin
            for (r = 0; r < rounds * N; r = r + 1) begin
                #1;
                sel          = {N{1'b0}};
                sel[r % N]   = 1'b1;
                if (grant === sel) begin
                    dir_pass = dir_pass + 1;
                end else begin
                    dir_fail = dir_fail + 1;
                    $error("rr_arbiter N=%0d: rotation step %0d granted %b, expected %b",
                           N, r, grant, sel);
                end
                @(negedge clk);
            end
        end
    endtask

    initial begin
        done  = 1'b0;
        rst_n = 1'b0;
        req   = {N{1'b0}};
        @(negedge clk);

        // 1. Everyone requesting from reset: strict rotation, longest fair wait.
        req = {N{1'b1}};
        @(negedge clk);
        rst_n = 1'b1;
        check_rotation(3);

        // 2. No requests: the pointer holds.
        req = {N{1'b0}};
        repeat (3) @(negedge clk);

        // 3. Each requester alone.
        for (s = 0; s < N; s = s + 1) begin
            sel    = {N{1'b0}};
            sel[s] = 1'b1;
            req    = sel;
            repeat (2) @(negedge clk);
            req = {N{1'b0}};
            @(negedge clk);
        end

        // 4. One held request among changing others.
        for (s = 0; s < N; s = s + 1) begin
            sel    = {N{1'b0}};
            sel[s] = 1'b1;
            for (t = 0; t < 4 * N; t = t + 1) begin
                next_rnd;
                req = rnd[N-1:0] | sel;
                @(negedge clk);
            end
        end

        // 5. Reset during traffic, then strict rotation from requester 0 again.
        req = {N{1'b1}};
        repeat (2) @(negedge clk);
        rst_n = 1'b0;
        @(negedge clk);
        rst_n = 1'b1;
        check_rotation(1);

        // 6. Random traffic, sparse and dense, with occasional resets.
        for (t = 0; t < 600; t = t + 1) begin
            next_rnd;
            if (rnd[31:28] == 4'd0) req = rnd[N-1:0];
            else                    req = rnd[N-1:0] | rnd[N+7:8];
            rst_n = (rnd[27:22] != 6'd0);
            @(negedge clk);
        end
        rst_n = 1'b1;
        req   = {N{1'b0}};
        repeat (2) @(negedge clk);

        // Coverage: every case the interface spec requires must be reached.
        if (chk_pass > 0) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d: the reference checker never ran", N);
        end
        if (cov_none > 0) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: no requests not reached", N);
        end
        if (cov_alone == {N{1'b1}}) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: each requester alone not reached (%b)", N, cov_alone);
        end
        if (cov_all > 0) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: everyone requesting not reached", N);
        end
        if (cov_held > 0) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: held request among changing others not reached", N);
        end
        if (max_wait == N - 1) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: longest wait was %0d, expected exactly %0d", N, max_wait, N - 1);
        end
        if (cov_rst > 0) dir_pass = dir_pass + 1;
        else begin
            dir_fail = dir_fail + 1;
            $error("rr_arbiter N=%0d coverage: reset during traffic not reached", N);
        end

        done = 1'b1;
    end

endmodule

module rr_arbiter_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire        done4;
    wire        done5;
    wire [31:0] passed4;
    wire [31:0] failed4;
    wire [31:0] passed5;
    wire [31:0] failed5;

    rr_arbiter_tb_harness #(.N(4), .SEED(32'h1F2E3D4C)) h_n4 (
        .clk    (clk),
        .done   (done4),
        .passed (passed4),
        .failed (failed4)
    );

    rr_arbiter_tb_harness #(.N(5), .SEED(32'h5A5A1234)) h_n5 (
        .clk    (clk),
        .done   (done5),
        .passed (passed5),
        .failed (failed5)
    );

    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        cycles;

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            $display("rr_arbiter_tb: no nirmaan_nonce plusarg given");
        cycles = 0;
        while (!(done4 && done5) && (cycles < 20000)) begin
            @(posedge clk);
            cycles = cycles + 1;
        end
        passed = passed4 + passed5;
        failed = failed4 + failed5;
        if (!(done4 && done5)) begin
            failed = failed + 1;
            $error("rr_arbiter_tb: timed out after %0d cycles", cycles);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
